n0:createOracleTrigger.n0:source:
CREATE OR REPLACE EDITIONABLE TRIGGER "%USER_NAME%"."SESSIONS_BFI" 
BEFORE INSERT
ON PEDS_MSTR.SESSIONS
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
BEGIN
    :new.s_id := NVL(:new.s_id, sessions_seq.nextval);

    IF :new.status = 'S' THEN
        :new.date_submitted := et_sysdate;
    END IF;
END;
/
